import heapq

def solution(times, n, k):
    graph = [[] for _ in range(n + 1)]   # graph[u] = [(v, w), ...]
    for u, v, w in times:
        graph[u].append((v, w))
    dist = {}                             # server -> final arrival time
    heap = [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)
        if u in dist:
            continue                      # a stale, slower entry
        dist[u] = d                       # smallest time popped first: it is final
        for v, w in graph[u]:
            if v not in dist:
                heapq.heappush(heap, (d + w, v))
    if len(dist) < n:
        return -1                         # some server never got the update
    return max(dist.values())

