def solution(times, n, k):
    # Bellman-Ford: relax every link, pass after pass, until nothing changes.
    # Up to n - 1 passes over all E links: O(n * E).
    big = float('inf')
    dist = [big] * (n + 1)
    dist[k] = 0
    for _ in range(n - 1):
        changed = False
        for u, v, w in times:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break
    best = max(dist[1:])
    return -1 if best == big else best
